import re
WORD = re.compile(r"[A-Za-z']+")

def tokenize(text):
    return [w.lower() for w in WORD.findall(text)]

def count_words(text):
    return len(tokenize(text))

def longest_word(text):
    words = tokenize(text)
    if not words:
        return ""
    return max(words, key=len)

def top_words(text, n=3):
    counts = {}
    for w in tokenize(text):
        counts[w] = counts.get(w, 0) + 1
    ordered = sorted(counts.items(), key=lambda kv: kv[1], reverse=True)
    return ordered[:n]

# Test cases from test_core.py
assert tokenize("Hello, World") == ["hello", "world"], f"tokenize failed: {tokenize('Hello, World')}"
assert count_words("one two  three") == 3, f"count_words failed: {count_words('one two  three')}"
assert longest_word("a bbb cc") == "bbb", f"longest_word failed: {longest_word('a bbb cc')}"
assert top_words("red red red blue blue green", 2) == [("red", 3), ("blue", 2)], f"top_words failed: {top_words('red red red blue blue green', 2)}"

print("All tests passed!")
